  const COCHANGE_LOOKBACK_SESSIONS = 5;
  const COCHANGE_TOP_N = 20;
  const CONVENTION_FILE_MAX_COUNT = 10;

  await appendReviewEvent(env.DB, {
    reviewId: review.id,
    eventType: 'review_context_assembly_started',
